import EventEmitter from 'eventemitter3';
import { WebSocketConnection } from './websocket-connection';
import { LongPollingConnection } from './long-polling-connection';
import { IServer, IServerConnection, IServerCommand, IConnectionOptions, IAutoReconnectConfig, IRealtimeServerEvents } from '../types';

export abstract class RealtimeServer extends EventEmitter<IRealtimeServerEvents> implements IServer {
    protected connection: IServerConnection;
    public get isConnected() { return this.connection.connected; }

    constructor(options: IConnectionOptions) {
        super();
        this.setupConnection(options);
    }

    private setupConnection(options: IConnectionOptions): IServerConnection {
        if (this.connection) {
            this.connection.destroy();
        }
        const connection = options.type === 'websocket' ? new WebSocketConnection(this, options) : new LongPollingConnection(this, options);
        this.connection = connection;
        return connection;
    }

    public connect(options?: IConnectionOptions): Promise<void> {
        if (options && this.connection.serverUrl !== options.serverUrl) {
            // switching endpoints: fully tear down the previous connection (socket + reconnect loop) before opening a new one
            return this.setupConnection(options).connect();
        }

        if (this.isConnected) {
            return Promise.resolve();
        }

        return this.connection.connect();
    }

    public disconnect(force: boolean = false): Promise<void> {
        return this.connection.disconnect(force);
    }

    public send(command?: IServerCommand): void {
        return this.connection.send(command);
    }

    public get unhandledDisconnection() {
        return !!this.connection.unhandledDisconnection;
    }

    public get isReconnecting() {
        return this.connection.isReconnecting;
    }

    public enableAutoReconnect(config?: IAutoReconnectConfig): void {
        this.connection.enableAutoReconnect(config);
    }

    public disableAutoReconnect(): void {
        this.connection.disableAutoReconnect();
    }

    public pauseReconnect(): void {
        this.connection.pauseReconnect();
    }

    public resumeReconnect(): void {
        this.connection.resumeReconnect();
    }
}
